package com.digitalhealth.controller;
import com.digitalhealth.dto.AuthDTO; import com.digitalhealth.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;} @PostMapping("/register") public AuthDTO.Response register(@Valid @RequestBody AuthDTO.Register d){return service.register(d);}@PostMapping("/login") public AuthDTO.OtpResponse login(@Valid @RequestBody AuthDTO.Login d){return service.login(d);}@PostMapping("/verify-otp") public AuthDTO.Response verify(@Valid @RequestBody AuthDTO.VerifyOtp d){return service.verifyOtp(d);}}
